const GLOBAL_KEY = Symbol.for("elementumEdk.engine.build.currentSourceText");
function slot() {
    return globalThis;
}
/**
 * Run `fn` (a workspace module import) with `filePath`'s own text available via
 * {@link currentSourceText} for the duration of the returned promise.
 */
export async function withSourceText(filePath, text, fn) {
    const g = slot();
    const previous = g[GLOBAL_KEY];
    g[GLOBAL_KEY] = { filePath, text };
    try {
        return await fn();
    }
    finally {
        g[GLOBAL_KEY] = previous;
    }
}
/** The file/text currently being imported via {@link withSourceText}, or undefined outside that context. */
export function currentSourceText() {
    return slot()[GLOBAL_KEY];
}
